import{_ as t,o as s,c as i,ao as a}from"./chunks/framework.BIwRTZjQ.js";const k=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"testing.md","filePath":"testing.md","lastUpdated":null}'),n={name:"testing.md"};function l(o,e,h,r,d,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="Testing" tabindex="-1">Testing <a class="header-anchor" href="#Testing" aria-label="Permalink to &quot;Testing {#Testing}&quot;">​</a></h1><p>The test suite is run with the <a href="https://docs.julialang.org/en/v1/stdlib/Pkg/" target="_blank" rel="noreferrer">Julia package manager</a>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg; Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ParallelStencil&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Each test file runs in its own Julia process. Test files can be selected by file name (selecting all files of this name, e.g. <code>test_parallel.jl</code> exists both in <code>test/</code> and in <code>test/ParallelKernel/</code>) or by path relative to the <code>test</code> folder; <code>--stop-on-fail</code> stops the test run at the first test file with failing tests:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg; Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ParallelStencil&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; test_args</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ParallelKernel/test_parallel.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--stop-on-fail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>The GPU packages (CUDA, AMDGPU and Metal) and Enzyme are not dependencies of the test environment (<code>test/Project.toml</code>): resolving the GPU packages all together holds each of them back to an old version, and Enzyme typically lags behind new Julia releases. The test runner installs them into the (temporary) test environment of <code>Pkg.test</code> as selected with the following environment variables (the tests of a selected GPU backend must run):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>PS_TEST_AD</code></td><td style="text-align:left;">Set to <code>0</code> to not install Enzyme into the test environment and skip the tests of automatic differentiation (default: <code>1</code>).</td></tr><tr><td style="text-align:left;"><code>PS_TEST_BACKEND</code></td><td style="text-align:left;">GPU backend to test (<code>CUDA</code>, <code>AMDGPU</code> or <code>Metal</code>): its package is installed into the test environment if it is not already, and the test run fails instead of skipping the tests of this backend if it is not functional.</td></tr></tbody></table><p>Without it, the CPU backends (Threads, Polyester and KernelAbstractions on the CPU) are tested, and the tests of a GPU backend run only if its package is already installed in the test environment and functional. For example, to test a GPU backend:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-vZ9wJ" id="tab-x8Rh8_o" checked><label data-title="Nvidia GPUs" for="tab-x8Rh8_o">Nvidia GPUs</label><input type="radio" name="group-vZ9wJ" id="tab-_4OmZH0"><label data-title="AMD GPUs" for="tab-_4OmZH0">AMD GPUs</label><input type="radio" name="group-vZ9wJ" id="tab-C-HiYT4"><label data-title="Apple GPUs" for="tab-C-HiYT4">Apple GPUs</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PS_TEST_BACKEND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CUDA</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;import Pkg; Pkg.test()&#39;</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PS_TEST_BACKEND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AMDGPU</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;import Pkg; Pkg.test()&#39;</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PS_TEST_BACKEND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Metal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;import Pkg; Pkg.test()&#39;</span></span></code></pre></div></div></div><p>The test environment of <code>Pkg.test</code> is temporary, so the installation is repeated at each test run (it is fast once the package is in the depot). To avoid it, the package can be added permanently to the test environment with <code>julia --project=test -e &#39;import Pkg; Pkg.add(&quot;CUDA&quot;)&#39;</code>; this modifies <code>test/Project.toml</code> (do not commit this change) and <code>test/Manifest.toml</code> (not tracked by git).</p><h2 id="Continuous-integration" tabindex="-1">Continuous integration <a class="header-anchor" href="#Continuous-integration" aria-label="Permalink to &quot;Continuous integration {#Continuous-integration}&quot;">​</a></h2><ul><li><p><strong>GitHub Actions</strong> (CPUs, and Apple GPUs on the macOS runners): Julia <code>min</code> and <code>1</code> on Linux and macOS (Apple silicon), and Julia <code>pre</code> on Linux (allowed to fail) (<code>.github/workflows/ci.yml</code>).</p></li><li><p><strong>CSCS CI</strong> on <a href="https://docs.cscs.ch/alps/" target="_blank" rel="noreferrer">Alps</a>, with one pipeline per vCluster:</p><ul><li><p><a href="https://docs.cscs.ch/clusters/daint/" target="_blank" rel="noreferrer">Daint</a> (Nvidia GH200 GPUs): the full test suite on one GH200 node, with the CPU backends running on the Grace CPU and the CUDA and KernelAbstractions backends on the GPU (<code>ci/cscs-gh200.yml</code>; <a href="https://gitlab.com/cscs-ci/ci-testing/webhook-ci/mirrors/7487078532071147/3127735853767612/-/pipelines" target="_blank" rel="noreferrer">pipelines</a>).</p></li><li><p><a href="https://docs.cscs.ch/clusters/beverin/" target="_blank" rel="noreferrer">Beverin</a> (AMD MI250X and MI300A GPUs): the full test suite on one node per GPU type, with the CPU backends running on the EPYC CPU and the AMDGPU and KernelAbstractions backends on the GPU (<code>ci/cscs-mi250.yml</code>, <code>ci/cscs-mi300.yml</code>; <a href="https://gitlab.com/cscs-ci/ci-testing/webhook-ci/mirrors/7487078532071147/3127735853767613/-/pipelines" target="_blank" rel="noreferrer">MI250X pipelines</a>, <a href="https://gitlab.com/cscs-ci/ci-testing/webhook-ci/mirrors/7487078532071147/3127735853767614/-/pipelines" target="_blank" rel="noreferrer">MI300A pipelines</a>).</p></li></ul><p>For pull requests by other contributors, a maintainer starts the pipelines by commenting <code>cscs-ci run</code>. Each job sets <code>PS_TEST_BACKEND</code> to the GPU backend it tests (<code>CUDA</code> on Daint, <code>AMDGPU</code> on Beverin and <code>Metal</code> on the macOS runners of GitHub Actions); the Linux jobs of GitHub Actions test the CPU backends only. The newest KernelAbstractions (0.10) and AMDGPU (2.9) require LLVM.jl 10, which Enzyme does not support yet: one Linux job and the MI300 job run without Enzyme (<code>PS_TEST_AD=0</code>) to test them, the other jobs test with Enzyme (KernelAbstractions 0.9).</p></li></ul><p>Coverage of all jobs is uploaded to <a href="https://app.codecov.io/gh/omlins/ParallelStencil.jl" target="_blank" rel="noreferrer">Codecov</a> (flags <code>cpu</code>, <code>gh200</code>, <code>mi250</code> and <code>mi300</code>).</p>`,13)])])}const g=t(n,[["render",l]]);export{k as __pageData,g as default};
